{
  "missing_information": [
    {
      "category": "decision",
      "gap": "No criteria defined for how a specific tool is selected for a given wafer measurement",
      "why_it_matters": "Without knowing the tool selection logic (e.g., based on wafer type, lot priority, tool availability, measurement type), it is impossible to model the branching logic or assess whether tool assignment can be automated"
    },
    {
      "category": "actor",
      "gap": "It is unclear who initiates the measurement request and whether multiple roles are involved across tool preparation and result recording",
      "why_it_matters": "Automation scope depends on knowing which actors perform which steps; if preparation and recording are done by different roles, handoff points and potential bottlenecks must be identified"
    },
    {
      "category": "system",
      "gap": "No information provided about the systems or interfaces used by the tools or for recording results",
      "why_it_matters": "Automation feasibility depends on whether tools expose APIs, generate structured output files, or require manual data entry; without this, integration constraints cannot be assessed"
    },
    {
      "category": "input",
      "gap": "The specific preparation steps per tool are not described, nor are the inputs required for each (e.g., recipes, calibration parameters, wafer identifiers)",
      "why_it_matters": "Each tool variant may require different inputs, and undocumented preparation steps represent hidden manual effort and potential failure points that must be captured for accurate process modeling"
    },
    {
      "category": "output",
      "gap": "The format, structure, and destination of the recorded measurement result are not specified",
      "why_it_matters": "If results are recorded in free text, a spreadsheet, or a proprietary format, data extraction and downstream automation will require different approaches; structured vs. unstructured output significantly changes automation complexity"
    },
    {
      "category": "exception",
      "gap": "No exception handling is described for scenarios such as tool unavailability, measurement failure, out-of-specification results, or calibration errors",
      "why_it_matters": "Exception paths are critical for robust automation; unhandled exceptions will cause process failures or require unplanned manual intervention, undermining automation reliability"
    },
    {
      "category": "frequency",
      "gap": "The volume and frequency of measurements (per shift, per day, per lot) and the distribution across tools are unknown",
      "why_it_matters": "Frequency and load distribution determine the ROI justification for automation and inform decisions about parallelism, scheduling, and resource allocation"
    },
    {
      "category": "manual_effort",
      "gap": "The time spent on preparation versus measurement versus result recording per tool is not quantified",
      "why_it_matters": "Without effort estimates per step and per tool, it is not possible to prioritize which subprocess to automate first or to calculate expected time savings"
    },
    {
      "category": "dependency",
      "gap": "It is unclear whether measurement must follow a specific upstream process step or whether there are sequencing constraints between tools",
      "why_it_matters": "Upstream dependencies affect when the workflow can be triggered and whether automation can proceed autonomously or must wait for external conditions to be met"
    },
    {
      "category": "data_availability",
      "gap": "It is not known whether historical measurement logs or tool usage records exist in a structured, queryable form",
      "why_it_matters": "Process mining and automation assessment rely on historical event data; if logs are incomplete or unstructured, conformance checking and variant analysis will be severely limited"
    },
    {
      "category": "risk_or_approval",
      "gap": "No approval or quality review step is mentioned after result recording, nor is it clear whether out-of-spec results trigger an escalation workflow",
      "why_it_matters": "If results require engineer sign-off or trigger corrective actions, these steps must be included in the process model; omitting them would produce an incomplete and potentially non-compliant automation design"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria determine which tool is selected for a given wafer measurement — for example, is the decision based on wafer type, measurement specification, tool availability, or engineer preference, and is this decision documented anywhere?",
      "targets": ["decision", "tool selection logic"]
    },
    {
      "id": "Q2",
      "question": "Can you walk through the specific preparation and measurement steps for each tool variant, and identify which of those steps require manual physical interaction versus software or parameter entry?",
      "targets": ["input", "manual_effort", "actor"]
    },
    {
      "id": "Q3",
      "question": "Where and in what format does the engineer record the measurement result — for example, a paper log, spreadsheet, MES system, or tool-generated report — and is that data accessible programmatically?",
      "targets": ["output", "system", "data_availability"]
    },
    {
      "id": "Q4",
      "question": "What happens when a measurement result is out of specification or when a tool fails mid-measurement — is there a defined escalation or rework path, and who is responsible for that decision?",
      "targets": ["exception", "risk_or_approval", "actor"]
    },
    {
      "id": "Q5",
      "question": "Approximately how many measurements are performed per shift or per day across all tools, and how evenly is the workload distributed between them?",
      "targets": ["frequency", "manual_effort"]
    },
    {
      "id": "Q6",
      "question": "Are there existing digital logs or event records from the measurement tools or surrounding systems that capture timestamps, tool IDs, wafer IDs, and outcomes in a structured format?",
      "targets": ["data_availability", "integration_constraint", "system"]
    }
  ]
}
